/* What libUE4SS.so exports on Linux: UE4SS's own API (C++ mods link against RC::) and Lua's C API
   (C++ mods that call Lua on a Lua mod's state: their own copy of Lua would have its own LuaLock,
   luauser.c's global lock). Everything else stays local. A preloaded library comes first in
   every lookup of the process, so an exported instantiation of a standard template
   (std::_Hashtable<std::u16string, ...>) would be used by any other library that has the same one -
   the game's plugins included (Mordhau's mod.io SDK aborted in modioInit with it). Lua's names carry
   the same risk: a game library with a Lua of its own would bind to this one. */
{
  global:
    extern "C++" {
      *RC::*;
      /* VirtualFunctionHelper.hpp's registry, which modules share because templates are per module.
         A mod with its own copy has an empty registry. Not in RC:: */
      SharedObjectManager::*;
    };
    lua_*;
    luaL_*;
    luaopen_*;
    /* LuaLibrary.hpp's extern "C" functions, which UE4SS.dll exports too: no RC:: in their names */
    get_lua_state_by_mod_name;
    execute_lua_in_mod;
    set_script_variable_int32;
    set_script_variable_default_data;
    call_script_function;
    is_ue4ss_initialized;
  local:
    *;
};
